package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

func main() {
	r := bufio.NewReader(os.Stdin)
	line, _ := r.ReadString('\n')
	parts := strings.Fields(line)
	nums := make([]int, 2)
	for i := 0; i < 2; i++ {
		nums[i], _ = strconv.Atoi(parts[i])
	}
	sort.Ints(nums)
	a, b := nums[0], nums[1]
	c := 7 - b
	g := gcd(c, 6)
	fmt.Printf("%d/%d\n", c/g, 6/g)
}

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

